import os
import sys

sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
import fastchacha


class Solver:
    def solve(self, problem, **kwargs):
        key = problem["key"]
        nonce = problem["nonce"]
        plaintext = problem["plaintext"]
        aad = problem["associated_data"]
        if aad:
            ct, tag = fastchacha.seal(key, nonce, plaintext, aad)
        else:
            ct, tag = fastchacha.seal(key, nonce, plaintext)
        return {"ciphertext": ct, "tag": tag}

