package main

import (
	"fmt"
	"runtime"
	"sync"
	"time"

	"bench/chacha20poly1305"
)

func main() {
	n := 40960000
	key := make([]byte, 32)
	for i := range key {
		key[i] = byte(i + 1)
	}
	nonce := make([]byte, 12)
	pt := make([]byte, n)
	for i := range pt {
		pt[i] = byte(i)
	}
	aead, _ := chacha20poly1305.New(key)

	for _, threads := range []int{1, 2, 4, 6, 8, 12} {
		runtime.GOMAXPROCS(threads)
		chunk := n / threads
		// prepare per-thread buffers
		pts := make([][]byte, threads)
		cts := make([][]byte, threads)
		for t := 0; t < threads; t++ {
			pts[t] = pt[t*chunk : (t+1)*chunk]
			cts[t] = make([]byte, chunk+16)
		}
		// warmup
		var wg sync.WaitGroup
		for t := 0; t < threads; t++ {
			wg.Add(1)
			go func(t int) {
				aead.Seal(cts[t][:0], nonce, pts[t], nil)
				wg.Done()
			}(t)
		}
		wg.Wait()

		iters := 3
		t0 := time.Now()
		for i := 0; i < iters; i++ {
			for t := 0; t < threads; t++ {
				wg.Add(1)
				go func(t int) {
					aead.Seal(cts[t][:0], nonce, pts[t], nil)
					wg.Done()
				}(t)
			}
			wg.Wait()
		}
		dt := time.Since(t0).Seconds() / float64(iters)
		fmt.Printf("threads=%2d  wall=%.4fs  aggregate=%.1f MB/s\n", threads, dt, float64(n)/dt/1e6)
	}
}
EOF
