// Parallel seal: splits plaintext into `threads` chunks, encrypts each as an
// independent ChaCha20-Poly1305 message with nonce = base_nonce XOR chunk index
// in the last byte, then concatenates. NOTE: this does NOT match the RFC output;
// used only for throughput experiments.
//
//export chacha_seal_parallel
func chacha_seal_parallel(key *C.uint8_t, nonce *C.uint8_t, pt *C.uint8_t, ptlen C.size_t, aad *C.uint8_t, aadlen C.size_t, out *C.uint8_t, threads C.int) {
	k := C.GoBytes(unsafe.Pointer(key), 32)
	baseNonce := C.GoBytes(unsafe.Pointer(nonce), 12)
	p := unsafe.Slice((*byte)(unsafe.Pointer(pt)), int(ptlen))
	var ad []byte
	if aadlen > 0 {
		ad = unsafe.Slice((*byte)(unsafe.Pointer(aad)), int(aadlen))
	}
	nt := int(threads)
	if nt < 1 {
		nt = 1
	}
	total := int(ptlen)
	// split into nt chunks (last absorbs remainder)
	base := total / nt
	var wg sync.WaitGroup
	off := 0
	outBase := unsafe.Slice((*byte)(unsafe.Pointer(out)), total+16*nt)
	for i := 0; i < nt; i++ {
		sz := base
		if i == nt-1 {
			sz = total - off
		}
		chunk := p[off : off+sz]
		dst := outBase[off+16*i : off+16*i+sz+16]
		nonce := make([]byte, 12)
		copy(nonce, baseNonce)
		nonce[11] ^= byte(i)
		wg.Add(1)
		go func(nonce, chunk, dst []byte) {
			defer wg.Done()
			aead, _ := chacha20poly1305.New(k)
