/*
 * ChaCha20-Poly1305 (RFC 8439) with a 4-block-parallel AVX2 ChaCha20
 * and an AVX2 Poly1305 (2 parallel accumulators). For benchmarking.
 */
#include <immintrin.h>
#include <stdint.h>
#include <string.h>
#include <stdio.h>
#include <stdlib.h>
#include <time.h>

static double now(void){struct timespec ts;clock_gettime(CLOCK_MONOTONIC,&ts);return ts.tv_sec+ts.tv_nsec*1e-9;}

#define ROTL(x,n) (((x)<<(n))|((x)>>(32-(n))))

static inline __m256i rotl_epi32(__m256i x, int n){
    return _mm256_or_si256(_mm256_slli_epi32(x, n), _mm256_srli_epi32(x, 32-n));
}

/* quarter round on 4 parallel states packed as columns: a,b,c,d are __m256i
   each holding one row-element across 4 blocks? We instead keep each state
   word as a vector of 4 lanes (one per block). */
static inline void qr4(__m256i *a,__m256i *b,__m256i *c,__m256i *d){
    *a = _mm256_add_epi32(*a, *b); *d = _mm256_xor_si256(*d, *a); *d = rotl_epi32(*d, 16);
    *c = _mm256_add_epi32(*c, *d); *b = _mm256_xor_si256(*b, *c); *b = rotl_epi32(*b, 12);
    *a = _mm256_add_epi32(*a, *b); *d = _mm256_xor_si256(*d, *a); *d = rotl_epi32(*d, 8);
    *c = _mm256_add_epi32(*c, *d); *b = _mm256_xor_si256(*b, *c); *b = rotl_epi32(*b, 7);
}

/* Generate 4 blocks (256 bytes) of keystream starting at counter `ctr`.
   out must be 256 bytes. */
static void chacha20_4blocks(const uint32_t key[8], const uint32_t nonce[3], uint32_t ctr, uint8_t out[256]){
    __m256i s0 = _mm256_set1_epi32(0x61707865);
    __m256i s1 = _mm256_set1_epi32(0x3320646e);
    __m256i s2 = _mm256_set1_epi32(0x79622d32);
    __m256i s3 = _mm256_set1_epi32(0x6b206574);
    __m256i s4 = _mm256_set1_epi32(key[0]);
    __m256i s5 = _mm256_set1_epi32(key[1]);
    __m256i s6 = _mm256_set1_epi32(key[2]);
    __m256i s7 = _mm256_set1_epi32(key[3]);
    __m256i s8 = _mm256_set1_epi32(key[4]);
    __m256i s9 = _mm256_set1_epi32(key[5]);
    __m256i s10= _mm256_set1_epi32(key[6]);
    __m256i s11= _mm256_set1_epi32(key[7]);
    __m256i s12= _mm256_setr_epi32(ctr, ctr+1, ctr+2, ctr+3, 0,0,0,0);
    s12 = _mm256_permute2x128_si256(s12, s12, 0x00); /* low 128 duplicated? no.
        setr_epi32 sets lanes 0..7. We only want 4 lanes. Use set_epi32. */
    s12 = _mm256_set_epi32(0,0,0,0, ctr+3, ctr+2, ctr+1, ctr);
    /* Actually lanes: _mm256_set_epi32(e7..e0). We want lanes 0..3 = ctr..ctr+3. */
    s12 = _mm256_set_epi32(ctr+3, ctr+2, ctr+1, ctr, ctr+3, ctr+2, ctr+1, ctr);
