    for(int i=0;i<10;i++){
        qr4(&w0,&w4,&w8,&w12); qr4(&w1,&w5,&w9,&w13); qr4(&w2,&w6,&w10,&w14); qr4(&w3,&w7,&w11,&w15);
        qr4(&w0,&w5,&w10,&w15); qr4(&w1,&w6,&w11,&w12); qr4(&w2,&w7,&w8,&w13); qr4(&w3,&w4,&w9,&w14);
