    _mm_storeu_si128((__m128i*)t[4], _mm256_castsi256_si128(w4));
    _mm_storeu_si128((__m128i*)t[5], _mm256_castsi256_si128(w5));
    _mm_storeu_si128((__m128i*)t[6], _mm256_castsi256_si128(w6));
    _mm_storeu_si128((__m128i*)t[7], _mm256_castsi256_si128(w7));
    _mm_storeu_si128((__m128i*)t[8], _mm256_castsi256_si128(w8));
    _mm_storeu_si128((__m128i*)t[9], _mm256_castsi256_si128(w9));
