                 uint8_t *out);

static PyObject *py_seal(PyObject *self, PyObject *args) {
    const uint8_t *key, *nonce, *pt, *aad = NULL;
    Py_ssize_t klen, nlen, ptlen, aadlen = 0;
    if (!PyArg_ParseTuple(args, "y#y#y#|y#", &key, &klen, &nonce, &nlen, &pt, &ptlen, &aad, &aadlen))
