    if (!buf) return PyErr_NoMemory();
    chacha_seal(key, nonce, pt, (size_t)ptlen, aadlen ? aad : NULL, (size_t)aadlen, buf);
    PyObject *ct = PyBytes_FromStringAndSize((const char *)buf, ptlen);
    PyObject *tag = PyBytes_FromStringAndSize((const char *)buf + ptlen, 16);
    free(buf);
    if (!ct || !tag) { Py_XDECREF(ct); Py_XDECREF(tag); return NULL; }
    PyObject *res = PyTuple_New(2);
    PyTuple_SET_ITEM(res, 0, ct);
    PyTuple_SET_ITEM(res, 1, tag);
    return res;
}

